def is_multiply_prime(a):
    """Write a function that returns true if the given number is the multiplication of 3 prime numbers
    and false otherwise.
    Knowing that (a) is less then 100. 
    Example:
    is_multiply_prime(30) == True
    30 = 2 * 3 * 5
    """
    if a < 1:
        return False

    # Check if a is divisible by 3
    if a % 3 != 0:
        return False

    # Try to find two more prime factors
    # We'll iterate through possible factors from 5 up to sqrt(a)
    for i in range(5, int(a**0.5) + 1):
        if a % i == 0:
            # i is a prime factor
            # Check if the remaining quotient is also prime
            remaining = a // i
            if remaining == 1:
                # a = i * 3 * 1, which means a = 3 * i. But we need 3 prime factors.
                # So this case is invalid unless i itself is prime and we have another factor.
                # Actually, if remaining == 1, then a = 3 * i. For this to be 3 primes,
                # i must be prime and we need one more factor. But the problem says "multiplication of 3 prime numbers".
                # So a = p1 * p2 * p3. If a = 3 * i, then either i = 1 (not prime) or i = p1 * p2.
                # But we already used 3 as a factor. So this case is invalid.
                return False
            elif remaining == 3:
                # a = 3 * 3 * i. So we have 3 * 3 * i. For this to be 3 primes, i must be prime.
                if is_prime(i):
                    return True
                else:
                    return False
            else:
                # a = 3 * i * remaining. We need to check if i and remaining are prime.
                if is_prime(i) and is_prime(remaining):
                    return True
                else:
                    return False
            break
    return False

